      `ROLLUP sheet=${sheet}-t by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ALIAS_ADDED sheet=${sheet}-t by=uma name=Ada alias=Addie`,
      `CLAIM_ADDED sheet=${sheet}-t by=uma person=Ada amount=1.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-t by=uma person=Ada amount=1.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet}-t by=uma person=Ada claimed=1.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=uma claimed-total=1.00 due-total=1.00 overdue-total=0.00`,
      `STATEMENT sheet=${sheet}-t by=uma name=Ada due-total=1.00 claims=1`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=addie from=${sheet}`,
      `PERSON_MERGED sheet=${sheet}-t by=vic from=addie into=Ada`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=31.00 due-total=7.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=31.00 due-total=7.00 overdue-total=0.00`
    ]);
  });
# POST /api/sheets/{sheetId}/people/{personId}/transfer — a steward transfers the person to another
# sheet by id (to): they arrive there with their grades, terms, contact, aliases and claims (renumbered
# on the other sheet) and leave this one entirely (see TransferPerson). Anyone else, a retired person,
# this sheet's own id, or a name, alias or contact already on the other sheet, is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonTransferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: arrive
arrive:
  class: net.officefloor.hq.app.person.RecordPersonArrived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the sheet to transfer to (trimmed): refused when none is named. */
public class ValidateTransfer {
    public void validate(@RequestBody TransferRequest request, Out<TransferRequest> body)
            throws InvalidPersonException {
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (to.isEmpty()) {
            throw new InvalidPersonException("No sheet to transfer to");
        }
        body.set(new TransferRequest(to));
    }
}
package net.officefloor.hq.app.person;

/** Body of a transfer: the id of the sheet the person is transferred to. */
public record TransferRequest(String to) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward transfers the person to another sheet: they arrive with every grade given them (and its
 *  from-date), their terms, contact and aliases, and their claims with their status, dates, notes,
 *  tags, frozen figures, logs and comments; each claim that had a number gets the other sheet's next,
 *  in the order the claims were opened (by the sheet's today then, then the order they were added).
 *  Figures a statement bound are lost, their statement count starts at 0, and references, holds and
 *  settle batches are not carried. They leave this sheet entirely: patron links (either way), pool
 *  memberships, watches and closed periods' fixed totals are dropped. Refused (nothing written) for
 *  anyone but a steward, a retired person, this sheet's own id or an archived sheet, and when their
 *  name, an alias or their contact is already on the other sheet. */
public class TransferPerson {
    public void transfer(@RequestParam(name = "by", required = false) String by,
            @Val TransferRequest request, @Val Person person, PersonRepository people,
            ClaimRepository claims, PeriodRepository periods, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Transfer> transferred) throws InvalidPersonException {
        String user = by == null ? "" : by;
        String sheetId = person.getSheetId();
        String to = request.to();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new InvalidPersonException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        if (person.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (sheets.isArchived(to)) {
            throw new InvalidPersonException("The sheet is archived: " + to);
        }
        if (people.nameTaken(to, person.getName(), null)
                || person.getAliases().stream().anyMatch((a) -> people.nameTaken(to, a, null))
                || (person.getContact() != null && people.contactTaken(to, person.getContact(), null))) {
            throw new InvalidPersonException("The name, an alias or the contact is already on " + to);
        }
        sheets.open(to, user);
        Rollup before = Rollup.of(to, people, claims, rates, sheets, settings);
        for (long id : claims.transferAll(sheetId, person.getId(), to)) {
            Claim claim = claims.find(to, id);
            claims.renumber(claim, ClaimNumbers.next(claim, claims, periods, settings, sheets));
        }
        people.transfer(person, to);
        transferred.set(new Transfer(person, to, before));
    }
}
