    public void merge(Person from, Person into, String user) {
        String sheetId = into.getSheetId();
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)",
                sheetId, into.getId(), from.getName(), user);
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
                into.getId(), sheetId, from.getId());
        for (Long patronId : from.getPatronIds()) {
            if (patronId != into.getId() && !into.getPatronIds().contains(patronId)) {
                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
                        sheetId, into.getId(), patronId, user);
                into.getPatronIds().add(patronId);
            }
        }
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
        // Whoever named from names into instead, unless that is into themselves or they name into already.
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN "
                + "(SELECT k.person_id FROM person_patron k WHERE k.sheet_id = ? AND k.patron_id = ?))",
                sheetId, from.getId(), into.getId(), sheetId, into.getId());
        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
                into.getId(), sheetId, from.getId());
        into.getPatronIds().remove(Long.valueOf(from.getId()));
        for (String table : List.of("person_statement", "person_hold", "person_watch", "person_grade",
                "person_grade_history", "person_retired_history", "person_retirement")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
        }
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
        withAliases(sheetId, List.of(into));
    }

    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
     *  statements dropped (the count back to 0); their holds, watchers, patron links (either way), pool
     *  memberships and closed periods' fixed totals are dropped; they keep the sheet they came from as their
     *  origin. Their claims must have moved first. */
    public void transfer(Person person, String to) {
        String sheetId = person.getSheetId();
        long id = person.getId();
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
        for (String table : List.of("person_statement", "person_hold", "person_watch", "pool_member")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        }
        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
        for (String table : List.of("person_grade", "person_grade_history", "person_retired_history", "person_retirement", "person_alias")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        }
        jdbc.update("UPDATE person SET sheet_id = ?, statement_count = 0, stated_total = NULL, statement_date = NULL, "
                + "origin = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?", to, sheetId, to, sheetId, id);
    }

    /** Swap the two people's places in their sheet's list. */
    public void swap(String sheetId, long a, long b) {
        Long posA = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, a);
        Long posB = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, b);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posB, sheetId, a);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posA, sheetId, b);
    }
}
    }

    /** Save a claim moved to another person: its person, its number (renumbered), its binding
     *  (dropped), and its place in the list, now the newest. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = ?, stated_due = ?, list_seq = "
                + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?",
                claim.getPersonId(), claim.getNumber(), claim.isStated(),
                claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getSheetId(), claim.getId());
        snapshot(claim.getSheetId(), claim.getId());
    }

    /** Move every claim of the person {@code fromId} to {@code intoId}, in the order they were added,
     *  each the newest in the list as it moves: their numbers and dates kept, any figure a statement
     *  bound dropped. */
    public void moveAll(String sheetId, long fromId, long intoId) {
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                Long.class, sheetId, fromId)) {
            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, list_seq = "
                    + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", intoId, sheetId, sheetId, id);
            snapshot(sheetId, id);
        }
    }

    /** Move every claim of the person to the sheet {@code to}, with their logs, comments and history,
     *  keeping their order in the list (each newer than the other sheet's): their status, dates, notes,
     *  tags and frozen figures kept, any figure a statement bound, their reference, lock and settle
     *  batch dropped, and their numbers taken away. The ids of those that had a number come back in
     *  the order they were opened (by the sheet's today then, then the order they were added), for
     *  {@link #renumber}. */
    public List<Long> transferAll(String sheetId, long personId, String to) {
        List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ? "
                + "AND c.number IS NOT NULL ORDER BY COALESCE((SELECT MIN(l.on_date) FROM claim_log l WHERE "
                + "l.claim_id = c.id AND l.status = 'OPEN'), (SELECT MIN(l.on_date) FROM claim_log l WHERE "
                + "l.claim_id = c.id AND l.status <> 'DRAFT'), c.claim_date), c.id", Long.class, sheetId, personId);
        long seq = jdbc.queryForObject("SELECT COALESCE(MAX(list_seq), 0) FROM claim WHERE sheet_id = ?", Long.class, to);
        for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq, id",
                Long.class, sheetId, personId)) {
            jdbc.update("UPDATE claim SET sheet_id = ?, list_seq = ?, number = NULL, stated = FALSE, stated_due = NULL, "
                    + "ref = NULL, ref_key = NULL, locked_by = NULL, settle_batch = NULL WHERE sheet_id = ? AND id = ?",
                    to, ++seq, sheetId, id);
            for (String table : List.of("claim_log", "claim_comment", "claim_history")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, sheetId, id);
            }
            snapshot(to, id);
            useTags(to, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, id));
        }
        return numbered;
    }

    /** Give a transferred claim its number on its new sheet. */
    public void renumber(Claim claim, String number) {
        jdbc.update("UPDATE claim SET number = ? WHERE sheet_id = ? AND id = ?", number, claim.getSheetId(), claim.getId());
        claim.setNumber(number);
    }

